'use strict';
const $=id=>document.getElementById(id);
const paths={map:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2z M9 3v16 M15 5v16',layers:'M3 8l9-5 9 5-9 5z M3 13l9 5 9-5 M3 18l9 5 9-5',plus:'M12 4v16 M4 12h16',settings:'M4 7h16 M4 17h16 M9 4v6 M16 14v6',tool:'M4 20l8-8 M14 3a6 6 0 007 7l-7 7-7-7 7-7z',table:'M3 4h18v16H3z M3 10h18 M3 15h18 M9 4v16',save:'M4 3h13l3 3v15H4z M8 3v6h8V3 M8 21v-7h8v7',target:'M12 2v5 M12 17v5 M2 12h5 M17 12h5 M12 5a7 7 0 110 14 7 7 0 010-14',close:'M5 5l14 14 M19 5L5 19',play:'M7 4l13 8-13 8z',point:'M12 6a6 6 0 110 12 6 6 0 010-12',polygon:'M4 6l10-3 7 9-6 9-11-4z',more:'M5 12h.1 M12 12h.1 M19 12h.1'};
function icon(key){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[key]||paths.layers}"/></svg>`}
document.querySelectorAll('[data-icon]').forEach(el=>el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon)));
let layers=[{name:'ایستگاه‌ها',source:'public.stations',type:'point'},{name:'محدودهٔ خدمات',source:'public.service_areas',type:'polygon'},{name:'محله‌های شهری',source:'public.neighborhoods',type:'polygon'}],selected=0,applied='#0f5c59',returnFocus=null,jobState='هنوز پردازشی اجرا نشده است.';
function notice(text){$('notice').textContent=text}
function draw(){const q=$('search').value;$('layerList').replaceChildren();layers.forEach((l,i)=>{if(!l.name.includes(q))return;const row=document.createElement('div');row.className='layer'+(selected===i?' selected':'');row.innerHTML=`<input type="checkbox" ${l.visible===false?'':'checked'} aria-label="نمایش ${l.name}">${icon(l.type)}<button class="name" aria-current="${selected===i?'true':'false'}"><span>${l.name}<small dir="ltr">${l.source}</small></span></button><button class="more" aria-label="ویژگی‌های ${l.name}">${icon('settings')}</button>`;row.querySelector('.name').onclick=()=>{selected=i;draw();notice('لایهٔ «'+l.name+'» انتخاب شد.')};row.querySelector('.more').onclick=e=>{selected=i;open('properties',e.currentTarget)};row.querySelector('input').onchange=e=>{l.visible=e.target.checked;notice(e.target.checked?'لایه روشن شد.':'لایه خاموش شد — نمونهٔ نمایشی')};$('layerList').append(row)})}draw();$('search').oninput=draw;
function open(id,trigger){returnFocus=trigger||document.activeElement;if(id==='tool'){$('tool').hidden=false;$('tool').querySelector('button').focus();return}if(id==='properties'){const l=layers[selected];savedSymbol=l.symbol||{color:'#0f5c59',size:'9',opacity:'100',labels:true};applied=savedSymbol.color;restoreSymbol();$('properties').querySelector('.heading b').lastChild.textContent='ویژگی‌های '+l.name;$('general').querySelector('input').value=l.name;const d=$('source').querySelectorAll('dd');d[0].textContent=l.source;d[1].textContent=l.type==='point'?'نقطه':'چندضلعی';d[3].textContent=l.source==='public.stations'?'۳':'نمایشی'}$ (id).showModal();if(id==='add')catalog()}
function close(id){if(id==='tool'){$('tool').hidden=true;returnFocus?.focus();return}if(id==='properties')preview(applied);$(id).close();returnFocus?.focus()}
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>open(b.dataset.open,b));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));$('properties').addEventListener('cancel',()=>preview(applied));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('tool').hidden){close('tool')}});
const available=[['پارک‌ها','public.parks','polygon'],['مراکز درمانی','public.clinics','point'],['ایستگاه‌ها','public.stations','point']];function catalog(){const q=$('catalogSearch').value;$('catalog').innerHTML=available.filter(l=>l[0].includes(q)||l[1].includes(q)).map(l=>{const exists=layers.some(x=>x.source===l[1]);return `<label class="catalogRow"><input type="checkbox" value="${l[1]}" ${exists?'disabled':''}>${icon(l[2])}<span>${l[0]}<small dir="ltr">${l[1]}</small></span><small>${exists?'در پروژه موجود است':l[2]==='point'?'نقطه':'چندضلعی'}</small></label>`}).join('')||'<p>لایه‌ای با این نام پیدا نشد.</p>'}$('catalogSearch').oninput=catalog;$('addSelected').onclick=()=>{const picks=[...$('catalog').querySelectorAll('input:checked')];if(!picks.length){$('catalogStatus').textContent='ابتدا حداقل یک لایه انتخاب کنید.';return}picks.forEach(p=>{const l=available.find(x=>x[1]===p.value);layers.push({name:l[0],source:l[1],type:l[2]})});draw();close('add');notice(picks.length+' لایه به پروژهٔ نمونه افزوده شد.')};
document.querySelectorAll('[data-property]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-property]').forEach(x=>x.classList.toggle('active',x===b));['appearance','general','source'].forEach(id=>$(id).hidden=id!==b.dataset.property)});
function preview(color){document.querySelectorAll('.map g[fill]').forEach(g=>g.setAttribute('fill',color))}$('color').oninput=e=>preview(e.target.value);$('size').oninput=e=>document.querySelectorAll('.map g[fill] circle').forEach(c=>c.setAttribute('r',e.target.value));$('apply').onclick=()=>{applied=$('color').value;notice('تغییرات اعمال شد؛ پروژه هنوز ذخیره نشده است.')};$('accept').onclick=()=>{$('apply').click();close('properties')};$('save').onclick=()=>notice('پروژهٔ نمونه ذخیره شد؛ این نمونه به سرور متصل نیست.');$('fit').onclick=()=>notice('نمای کامل نقشهٔ نمایشی');
function table(){ $('resultBody').innerHTML='<table><thead><tr><th>شناسه</th><th>نام ایستگاه</th><th>نوع</th></tr></thead><tbody><tr><td>۱</td><td>مرکزی</td><td>اتوبوس</td></tr><tr><td>۲</td><td>باغستان</td><td>اتوبوس</td></tr><tr><td>۳</td><td>پارک</td><td>مترو</td></tr></tbody></table>'}
$('tableToggle').onclick=()=>{$('results').hidden=false;table()};$('resultsClose').onclick=()=>{$('results').hidden=true;$('tableToggle').focus()};$('attributes').onclick=()=>{table();$('attributes').classList.add('active');$('jobs').classList.remove('active')};$('jobs').onclick=()=>{$('resultBody').textContent=jobState;$('jobs').classList.add('active');$('attributes').classList.remove('active')};$('toolForm').onsubmit=e=>{e.preventDefault();$('toolStatus').textContent='در حال اجرای نمونه…';$('toolForm').querySelector('button').disabled=true;setTimeout(()=>{jobState='حریم '+$('distance').value+' متری — نمونه با موفقیت پایان یافت.';$('toolStatus').textContent=jobState;$('toolForm').querySelector('button').disabled=false;notice('نتیجهٔ نمایشی آماده است.');$('buffer').setAttribute('r',Math.min(160,Number($('distance').value)/5));},700)};
$('contentsToggle').onclick=()=>{$('contents').classList.add('open');$('contentsClose').focus()};$('contentsClose').onclick=()=>{$('contents').classList.remove('open');$('contentsToggle').focus()};

// Draft مستقل نمونه: بستن بدون اعمال، تمام کنترل‌های نماد را بازمی‌گرداند.
let savedSymbol={color:'#0f5c59',size:'9',opacity:'100',labels:true};
function symbolDraft(){return {color:$('color').value,size:$('size').value,opacity:$('opacity').value,labels:$('labels').checked}}
function renderSymbol(v){preview(v.color);document.querySelectorAll('.map g[fill] circle').forEach(c=>c.setAttribute('r',v.size));document.querySelectorAll('.map g[fill]').forEach(g=>g.setAttribute('opacity',Number(v.opacity)/100));document.querySelector('.map g[font-size]').style.visibility=v.labels?'visible':'hidden'}
function restoreSymbol(){for(const key of ['color','size','opacity'])$(key).value=savedSymbol[key];$('labels').checked=savedSymbol.labels;renderSymbol(savedSymbol)}
['color','size','opacity','labels'].forEach(id=>$(id).addEventListener('input',()=>renderSymbol(symbolDraft())));
$('properties').addEventListener('close',restoreSymbol);$('properties').addEventListener('cancel',restoreSymbol);
$('apply').onclick=()=>{savedSymbol=symbolDraft();layers[selected].symbol={...savedSymbol};applied=savedSymbol.color;notice('تغییرات اعمال شد؛ پروژه هنوز ذخیره نشده است.')};
$('accept').onclick=()=>{$('apply').click();close('properties')};
$('properties').querySelector('h2').textContent='تنظیم نماد لایه';
$('toolForm').addEventListener('submit',()=>{jobState='حریم '+$('distance').value+' متری — اجرای نمایشی در حال انجام';});
